// Designed, mirror-symmetric map generated by scripts/generate-raas-map.py.
// (The earlier OpenStreetMap import, leipalingis-osm.json, is kept for reference.)
import source from './leipalingis-map.json';
import { MAP_COLS, MAP_ROWS } from '../constants';

// The stored OSM projection is independent of the gameplay grid. Reproject
// every feature together, retaining the same geographic bounds and provenance.
export const GEOGRAPHIC_SCALE_X = MAP_COLS / source.grid[0];
export const GEOGRAPHIC_SCALE_Y = MAP_ROWS / source.grid[1];
export const GEOGRAPHIC_SCALE = Math.min(GEOGRAPHIC_SCALE_X, GEOGRAPHIC_SCALE_Y);
export const projectSourcePoint = (p: number[]): number[] => [p[0] * GEOGRAPHIC_SCALE_X, p[1] * GEOGRAPHIC_SCALE_Y];
export const geography = {
  ...source,
  roads: source.roads.map(r => ({ ...r, points: r.points.map(projectSourcePoint) })),
  areas: source.areas.map(a => ({ ...a, points: a.points.map(projectSourcePoint),
    holes: ((a as { holes?: number[][][] }).holes ?? []).map(r => r.map(projectSourcePoint)) })),
  buildings: source.buildings.map(([x, y, angle]) => [...projectSourcePoint([x, y]), angle]),
  places: source.places.map(p => ({ ...p, point: projectSourcePoint(p.point) })),
  /** Designed-map extras (absent in the old OSM import). */
  designed: (source as { style?: string }).style === 'designed',
  streams: ((source as { streams?: number[][][] }).streams ?? []).map(s => s.map(projectSourcePoint)),
  fords: ((source as { fords?: number[][] }).fords ?? []).map(projectSourcePoint),
  hedges: ((source as { hedges?: number[][][] }).hedges ?? []).map(h => h.map(projectSourcePoint)),
};
/** Playable rectangle in gameplay cells [x0, y0, x1, y1]; outside it is scenery. */
export const PLAYABLE_CELLS = [source.playable[0] * GEOGRAPHIC_SCALE_X, source.playable[1] * GEOGRAPHIC_SCALE_Y,
  source.playable[2] * GEOGRAPHIC_SCALE_X, source.playable[3] * GEOGRAPHIC_SCALE_Y] as const;
/** Main deployment areas (not objectives), gameplay cells. */
export const MAIN_CELLS = { north: projectSourcePoint(source.mains.north), south: projectSourcePoint(source.mains.south) };
